import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { PageHeader } from "@/components/admin/ui";
import { ProductEditor } from "@/components/admin/ProductEditor";
import { categoryOptions } from "../categoryOptions";

const r = (paise: number | null) => (paise === null ? "" : String(paise / 100));

export default async function EditProductPage({ params }: PageProps<"/admin/products/[id]">) {
  const { id } = await params;
  const [p, categories] = await Promise.all([
    db.product.findUnique({ where: { id }, include: { images: { orderBy: { sortOrder: "asc" } } } }),
    categoryOptions(),
  ]);
  if (!p) notFound();
  return (
    <>
      <PageHeader title="Edit product" description={p.name} actions={<Link href={`/product/${p.slug}`} target="_blank" className="btn-outline">View on store</Link>} />
      <ProductEditor
        categories={categories}
        initial={{
          id: p.id, name: p.name, slug: p.slug, sku: p.sku, brand: p.brand ?? "", material: p.material ?? "", categoryId: p.categoryId,
          shortDescription: p.shortDescription ?? "", description: p.description, price: r(p.price), mrp: r(p.mrp), costPrice: r(p.costPrice),
          gstRate: p.gstRate, hsnCode: p.hsnCode ?? "", stock: p.stock, lowStockThreshold: p.lowStockThreshold,
          weightGrams: p.weightGrams ? String(p.weightGrams) : "", warranty: p.warranty ?? "", tags: p.tags.join(", "),
          specs: Array.isArray(p.specs) ? (p.specs as { label: string; value: string }[]) : [],
          images: p.images.map((i) => ({ url: i.url, alt: i.alt ?? "" })),
          isActive: p.isActive, isFeatured: p.isFeatured, emiEligible: p.emiEligible, engravingAvailable: p.engravingAvailable,
        }}
      />
    </>
  );
}
